import{_ as a,o as i,c as t,ae as l}from"./chunks/framework.RRduUuAx.js";const p=JSON.parse('{"title":"heliosApp Constitution","description":"","frontmatter":{},"headers":[],"relativePath":"reference/constitution.md","filePath":"reference/constitution.md"}'),r={name:"reference/constitution.md"};function o(n,e,s,c,d,u){return i(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="heliosapp-constitution" tabindex="-1">heliosApp Constitution <a class="header-anchor" href="#heliosapp-constitution" aria-label="Permalink to &quot;heliosApp Constitution&quot;">​</a></h1><blockquote><p>Created: 2026-02-26 Updated: 2026-02-27 Version: 2.0.0</p></blockquote><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>This constitution captures the technical standards, code quality expectations, tribal knowledge, and governance rules for heliosApp — a terminal-first desktop IDE built on an ElectroBun fork of co(lab). All features and pull requests should align with these principles.</p><h2 id="technical-standards" tabindex="-1">Technical Standards <a class="header-anchor" href="#technical-standards" aria-label="Permalink to &quot;Technical Standards&quot;">​</a></h2><h3 id="languages-and-frameworks" tabindex="-1">Languages and Frameworks <a class="header-anchor" href="#languages-and-frameworks" aria-label="Permalink to &quot;Languages and Frameworks&quot;">​</a></h3><ul><li><strong>Primary language</strong>: TypeScript (TS7-native) on Bun runtime. <ul><li>This is a desktop app built on ElectroBun (TypeScript-native). Go is not feasible for the core system. See <code>docs/adrs/ADR-001-typescript-over-go.md</code>.</li></ul></li><li><strong>Supporting languages</strong> (where appropriate): <ul><li>Rust, Zig: Performance-critical native modules, renderer integration, system-level bindings.</li><li>Python: CPython 3.14 preferred, PyPy 3.11 acceptable — for tooling and automation scripts only.</li></ul></li><li><strong>Desktop shell</strong>: ElectroBun (forked from co(lab) by Blackboard).</li><li><strong>Terminal renderers</strong>: ghostty (primary) + rio (secondary, feature-flagged).</li><li><strong>Mux/orchestration</strong>: zellij (session multiplexing), par (lane-based worktree execution), zmx (checkpoint/restore).</li><li><strong>Collaboration</strong>: upterm + tmate (share-session workflows, post-MVP).</li><li><strong>Protocol stack</strong>: Internal local bus (<code>helios.localbus.v1</code>) + ACP + MCP + A2A for agent interop.</li><li>Reuse proven patterns and artifacts from related repos (for example <code>../thegent</code>, <code>../trace</code>) where applicable.</li></ul><h3 id="testing-requirements" tabindex="-1">Testing Requirements <a class="header-anchor" href="#testing-requirements" aria-label="Permalink to &quot;Testing Requirements&quot;">​</a></h3><ul><li>Primary testing stack: Vitest + Playwright (Jest is not the preferred framework).</li><li>Coverage target: 85-95% minimum, with continuous optimization toward 100% where feasible.</li><li>Rust code should maintain near-full coverage.</li><li>Full test pyramid is required (unit, integration, e2e) with broad validation depth.</li><li>Include advanced quality validation as part of testing strategy: <ul><li>Static and active analyzers.</li><li>Performance regression tests (including linear-regression-style trend tracking).</li><li>Security testing.</li><li>Chaos/resilience testing.</li><li>Requirements traceability checks.</li></ul></li><li>Assume minimal direct human feedback; validation depth must compensate.</li></ul><h3 id="performance-and-scale" tabindex="-1">Performance and Scale <a class="header-anchor" href="#performance-and-scale" aria-label="Permalink to &quot;Performance and Scale&quot;">​</a></h3><ul><li>Device-first runtime model; cloud deployment is not the default target.</li><li>Cloud usage, if any, is limited to user-owned/personal infrastructure (VPS, Supabase, personal remote machine).</li><li>User concurrency is secondary; primary target is tab/session/agent concurrency.</li><li>Target operating envelope: approximately 300-1000 concurrent tabs/sessions on an 8 GB RAM, 4-core CPU device.</li><li>Terminal rendering SLOs: <ul><li>Input-to-echo latency: p50 &lt; 30ms, p95 &lt; 60ms.</li><li>Input-to-render latency: p50 &lt; 60ms, p95 &lt; 150ms.</li><li>Renderer frame stability: 60 FPS target on active pane.</li><li>Startup to interactive: &lt; 2 seconds.</li><li>Memory: &lt; 500 MB steady-state for typical workload (25 active terminals).</li></ul></li></ul><h3 id="deployment-and-constraints" tabindex="-1">Deployment and Constraints <a class="header-anchor" href="#deployment-and-constraints" aria-label="Permalink to &quot;Deployment and Constraints&quot;">​</a></h3><ul><li>Dockerless by default.</li><li>Preferred execution modes: <ul><li><code>proc-compose</code> local process orchestration.</li><li>Native execution.</li><li>Low-overhead/high-performance container or sandbox systems when needed.</li></ul></li><li>Deployment/runtime choices must prioritize low overhead and high local efficiency.</li></ul><h2 id="code-quality" tabindex="-1">Code Quality <a class="header-anchor" href="#code-quality" aria-label="Permalink to &quot;Code Quality&quot;">​</a></h2><h3 id="pull-request-requirements" tabindex="-1">Pull Request Requirements <a class="header-anchor" href="#pull-request-requirements" aria-label="Permalink to &quot;Pull Request Requirements&quot;">​</a></h3><ul><li>Every PR must be reviewed by another agent.</li><li>Automated review gates (GCA and CodeRabbit) are required and count as approval gates.</li><li>If review tooling is rate-limited, re-review must be requested before merge.</li><li>Self-merge is allowed after all required gates pass.</li></ul><h3 id="code-review-checklist" tabindex="-1">Code Review Checklist <a class="header-anchor" href="#code-review-checklist" aria-label="Permalink to &quot;Code Review Checklist&quot;">​</a></h3><p>Reviewers must validate at minimum:</p><ul><li>Correctness, clarity, and maintainability.</li><li>Tests added/updated appropriately.</li><li>Documentation and docstrings updated where needed.</li><li>Type quality and robust error handling.</li><li>Performance implications (especially terminal hot path).</li><li>Security risks.</li><li>Anti-pattern detection and remediation.</li><li>Preference for well-vetted libraries over unnecessary hand-rolled implementations.</li><li>Avoidance of excessive backward-compatibility/fallback code paths.</li><li>Regression risks across versions and code paths.</li></ul><h3 id="quality-gates" tabindex="-1">Quality Gates <a class="header-anchor" href="#quality-gates" aria-label="Permalink to &quot;Quality Gates&quot;">​</a></h3><ul><li>All defined gates must pass at maximum strictness.</li><li>No ignores, skips, or excludes for required quality checks.</li></ul><h3 id="documentation-standards" tabindex="-1">Documentation Standards <a class="header-anchor" href="#documentation-standards" aria-label="Permalink to &quot;Documentation Standards&quot;">​</a></h3><ul><li>Full-spectrum documentation is required: <ul><li>Public API docs/docstrings with examples where applicable.</li><li>ADRs for architectural choices and exceptions.</li><li>Debug/investigation notes.</li><li>Research documents.</li><li>Feature plans.</li><li>Retrospectives.</li><li>End-to-end operational documentation.</li></ul></li><li>Documentation quality is subject to governance review.</li></ul><h2 id="tribal-knowledge" tabindex="-1">Tribal Knowledge <a class="header-anchor" href="#tribal-knowledge" aria-label="Permalink to &quot;Tribal Knowledge&quot;">​</a></h2><h3 id="team-conventions" tabindex="-1">Team Conventions <a class="header-anchor" href="#team-conventions" aria-label="Permalink to &quot;Team Conventions&quot;">​</a></h3><ul><li>Reuse established conventions from related repos where they remain applicable.</li><li>File size targets: <ul><li>Preferred: 150-350 lines.</li><li>Hard limit: 500 lines.</li></ul></li><li>Design for generic, scalable, extensible, and modular shared code from day one.</li><li>Follow Hexagonal architecture and SOLID/KISS/DRY/Clean principles.</li><li>Practice TDD/BDD/SDD as standard engineering workflow patterns.</li><li><strong>Control plane / data plane separation</strong>: Keep PTY byte path off UI thread. Terminal rendering is the hot path; orchestration is async.</li><li><strong>Bounded buffers and explicit backpressure</strong>: No unbounded arrays or memory runaway in terminal output paths.</li><li><strong>Graceful degradation</strong>: External failures (tool/A2A/harness) isolate to lane-level, never crash global runtime.</li></ul><h3 id="lessons-learned" tabindex="-1">Lessons Learned <a class="header-anchor" href="#lessons-learned" aria-label="Permalink to &quot;Lessons Learned&quot;">​</a></h3><ul><li>Apply lessons learned from related prior repos by default.</li><li>Prefer <code>bun</code> and <code>uv</code> over <code>npm</code> and <code>pip</code> where the toolchain allows.</li><li>Carry forward broad best practices already validated in adjacent projects.</li><li><strong>Fork before build</strong>: When starting from an existing app (co(lab)), fork and strip first — don&#39;t rewrite from scratch. Prove the product thesis (keystroke → PTY → render → screen) before formalizing protocol compliance.</li></ul><h3 id="historical-decisions" tabindex="-1">Historical Decisions <a class="header-anchor" href="#historical-decisions" aria-label="Permalink to &quot;Historical Decisions&quot;">​</a></h3><ul><li>Historical architectural decisions should be sourced from prior repos and used as guiding precedent.</li><li>See <code>docs/adrs/</code> for project-specific architectural decision records.</li></ul><h2 id="governance" tabindex="-1">Governance <a class="header-anchor" href="#governance" aria-label="Permalink to &quot;Governance&quot;">​</a></h2><h3 id="amendment-process" tabindex="-1">Amendment Process <a class="header-anchor" href="#amendment-process" aria-label="Permalink to &quot;Amendment Process&quot;">​</a></h3><ul><li>Constitution amendments require 2-3 agent review loops before acceptance.</li></ul><h3 id="compliance-validation" tabindex="-1">Compliance Validation <a class="header-anchor" href="#compliance-validation" aria-label="Permalink to &quot;Compliance Validation&quot;">​</a></h3><ul><li>Agents and code reviewers validate constitution compliance and block merge when violated.</li></ul><h3 id="exception-handling" tabindex="-1">Exception Handling <a class="header-anchor" href="#exception-handling" aria-label="Permalink to &quot;Exception Handling&quot;">​</a></h3><ul><li>Exceptions must be documented in an ADR.</li><li>Exceptions require 3 approvals.</li><li>Each exception must include a defined sunset date (or explicit justification for permanence).</li></ul>',37)])])}const m=a(r,[["render",o]]);export{p as __pageData,m as default};
